def special_for(case,preds,th,arcs):
    S=len(case['slots']);J=len(case['windows']);K,R,Z,a,b,e,w,z,h=make_nodes(S,J,len(case['flows']),len(case['groups']))
    elig=[];mat=[[-1]*S for _ in range(J)];elig_slot=[-1]*len(arcs);elig_win=[-1]*len(arcs);zero=[]
