            elig.append((i,ss,j));mat[j][ss]=i;elig_slot[i]=ss;elig_win[i]=j
        else:zero.append(i)
    slots=case['slots'];wins=case['windows'];vals=case['class_values'];W=1+J*slots[-1][0]
